def addfield(rid, text):
    global s
    ls = s.split("\n")
    hit = [i for i, l in enumerate(ls) if re.match(r"^[A-Z_]+\|id=" + rid + r"\|", l)]
    assert len(hit) == 1 and ls[hit[0]].count("|tag=") == 1 and " " not in text
    ls[hit[0]] = ls[hit[0]].replace("|tag=", "|v2_launch=" + text + "|tag=")
    s = "\n".join(ls)
