    fa = [tuple(x.split("=", 1)) for x in RA[i].split("|")[1:]]; fb = [tuple(x.split("=", 1)) for x in RB2[i].split("|")[1:]]
    da, db = dict(fa), dict(fb)
    assert all(k in db for k, _ in fa) and RA[i].split("|")[0] == RB2[i].split("|")[0]
    ch = [k for k, v in fa if db[k] != v]; ad = [k for k, _ in fb if k not in da]
